arguments.argument:
if sys_key.key_check{exit}
for(i=0; i!=9; i+=1)
{
    if keyboard_check_pressed(i+49)
    {
        vaz=i
        with(sys_mouse)
        {
            if vab_unit=1
            {
                if instance_number(vab_unit_id[0])
                {
                    if global.player_control=vab_unit_id[0].player and vab_unit_id[0].skil_number>other.vaz
                    {
                        if global.player_moni[global.player_control]>=global.units_moni[vab_unit_id[0].skil_id[other.vaz]]
                        {
                            if vab_unit_id[0].skil_exe[other.vaz]=0
                            {
                                sys_mouse.bil_ok=1
                                sys_mouse.bil_id=vab_unit_id[0].skil_id[other.vaz]
                                vab_unit=0
                                global.player_moni[global.player_control]-=global.units_moni[vab_unit_id[0].skil_id[other.vaz]]
                                with(vab_unit_id[0])
                                {
                                    /*on*/buffer_clear(fnv_sned)
                                    write_uint(fnv_sned, on)
                                    fn_message_send(global.socket, send_other, 20)
                                    
                                    pos=ds_list_find_index(global.on_unit, string(on))
                                    ds_list_delete(global.on_unit, pos)
                                    ds_list_delete(global.on_unit, pos)
                                    
                                    instance_destroy()
                                }
                            }
                            else
                            {
                                if vab_unit_id[0].unit_cre_number!=6
                                {
                                    vab_unit_id[0].unit_cre_id[vab_unit_id[0].unit_cre_number]=vab_unit_id[0].skil_id[other.vaz]
                                    if vab_unit_id[0].unit_cre_number=0{vab_unit_id[0].unit_cre_time=global.moni_alarm[vab_unit_id[0].skil_id[other.vaz]]}
                                    vab_unit_id[0].unit_cre_number+=1
                                    global.player_moni[global.player_control]-=global.units_moni[vab_unit_id[0].skil_id[other.vaz]]
                                }
                                else
                                {
                                    other.info_text=ml2_show_4
                                    other.alarm[0]=room_speed*2
                                    sound_play(ml_sound1)
                                }
                            }
                        }
                        else
                        {
                            other.info_text=ml2_show_1
                            other.alarm[0]=room_speed*2
                            sound_play(ml_sound1)
                        }
                    }
                }
            }
        }
    }
}
